R=sp.Rational
x,y=sp.symbols('x y',real=True)
def put(group,n,steps,errors):
 author.add('PS3',f'{group:03}-{n:03}',steps,errors,'逐问检查联合支持、条件样本空间、边缘求和或积分、归一化及独立性条件。')
def example(n,steps,errors):
 author.add_example('PS3',n,steps,errors,'展开联合与条件计算，检查取值顺序、积分边界及独立性须几乎处处成立。')
def joint(xs,ys,P,label,marginals=False,independent=None):
 assert P.shape==(len(xs),len(ys)) and sum(P)==1 and all(p>=0 for p in P)
 rows=[sum(P[i,j] for j in range(P.cols)) for i in range(P.rows)]
 cols=[sum(P[i,j] for i in range(P.rows)) for j in range(P.cols)]
 table='| X / Y | '+' | '.join('$'+L(v)+'$' for v in ys)+' |\n|---|'+'---|'*len(ys)+'\n'
 for i,a in enumerate(xs):table+='| $'+L(a)+'$ | '+' | '.join('$'+L(P[i,j])+'$' for j in range(P.cols))+' |\n'
 out=['**'+label+'。** 行固定X，列固定Y。每格是两个条件同时满足的联合概率；未列为可能的组合补0。\n\n'+table,'全表非负且全部格子和1，横行竖列的坐标顺序不可互换。']
 if marginals or independent is not None:
  for i,a in enumerate(xs):out+=['沿该行求和得 $$P(X='+L(a)+')='+ '+'.join(L(P[i,j]) for j in range(P.cols))+'='+L(rows[i])+'.$$']
  for j,b in enumerate(ys):out+=['沿该列求和得 $$P(Y='+L(b)+')='+ '+'.join(L(P[i,j]) for i in range(P.rows))+'='+L(cols[j])+'.$$']
 if independent is not None:
  mismatch=[(i,j) for i in range(P.rows) for j in range(P.cols) if P[i,j]!=rows[i]*cols[j]]
  assert bool(mismatch)==(not independent)
  if mismatch:
   i,j=mismatch[0];out+=['检验这一格已足够否定独立：$$P(X='+L(xs[i])+',Y='+L(ys[j])+')='+L(P[i,j])+r'\ne '+L(rows[i]*cols[j])+'=P(X='+L(xs[i])+')P(Y='+L(ys[j])+r').$$因此不独立。']
  else:
   for i,a in enumerate(xs):out+=['第'+str(i+1)+'行逐格与边缘乘积核对：$$'+r',\quad '.join('('+L(rows[i])+')('+L(cols[j])+')='+L(P[i,j]) for j in range(P.cols))+r'.$$']
   out+=['全部支持格及支持外的零概率格均满足联合等于边缘乘积，故X、Y独立。不是仅某一格相等就宣布独立。']
 return out
def conditional(xs,ys,P,axis,value):
 if axis=='X':i=xs.index(value);values=ys;weights=list(P.row(i));name='Y';condition='X='+L(value)
 else:j=ys.index(value);values=xs;weights=list(P.col(j));name='X';condition='Y='+L(value)
 d=sum(weights);assert d>0
 out=['给定 $'+condition+'$，条件分母是该'+('行' if axis=='X' else '列')+'的边缘概率 $$P('+condition+')='+ '+'.join(L(w) for w in weights)+'='+L(d)+r'>0.$$把这一'+('行' if axis=='X' else '列')+'的每格除同一个分母。']
 out+=['于是 $$P('+name+'='+L(v)+r'\mid '+condition+r')=\frac{'+L(w)+'}{'+L(d)+'}='+L(sp.cancel(w/d))+'.$$' for v,w in zip(values,weights)]
 out+=['这些条件概率之和1，条件支撑外为0；分母若为0则此离散条件分布不能这样定义。']
 return out
def double(f,inner,a,b,outer,c,d,label):
 h=sp.simplify(sp.integrate(f,(inner,a,b)));value=sp.simplify(sp.integrate(h,(outer,c,d)))
 return ['**'+label+'。** 根据事件与联合支持的交集确定积分界，先对'+str(inner)+'、后对'+str(outer)+'积分：$$\int_{'+L(c)+'}^{'+L(d)+r'}\int_{'+L(a)+'}^{'+L(b)+'}('+L(f)+r')\,d'+L(inner)+r'\,d'+L(outer)+r'.$$',r'内积分得到 $$'+L(h)+r'.$$再作外积分 $$\int_{'+L(c)+'}^{'+L(d)+'}('+L(h)+r')\,d'+L(outer)+'='+L(value)+r'.$$支持边界为零面积集合，是否含边界不影响概率。']

